--
-- TOC entry 2153 (class 1255 OID 100560)
-- Name: period_end(date, character); Type: FUNCTION; Schema: ssot; Owner: fa
--

CREATE FUNCTION ssot.period_end(p_start date, p_freq character) RETURNS date
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  SELECT CASE p_freq
    WHEN 'A' THEN (p_start + INTERVAL '1 year'   - INTERVAL '1 day')::date
    WHEN 'Q' THEN (p_start + INTERVAL '3 months' - INTERVAL '1 day')::date
    WHEN 'M' THEN (p_start + INTERVAL '1 month'  - INTERVAL '1 day')::date
    WHEN 'D' THEN p_start
  END
$$;


ALTER FUNCTION ssot.period_end(p_start date, p_freq character) OWNER TO fa;

