-- Name: as_of(timestamp with time zone); Type: FUNCTION; Schema: ssot; Owner: fa
--

CREATE FUNCTION ssot.as_of(p_asof timestamp with time zone) RETURNS SETOF ssot.country_vintages
    LANGUAGE sql STABLE
    AS $$
  SELECT * FROM ssot.country_vintages
  WHERE current_since <= p_asof AND p_asof < coalesce(valid_to, 'infinity'::timestamptz)
$$;


