--
-- TOC entry 1790 (class 1259 OID 100925)
-- Name: country360_wide; Type: VIEW; Schema: ssot; Owner: fa
--

CREATE VIEW ssot.country360_wide AS
 WITH own AS (
         SELECT country360.geo_code,
            country360.frequency,
            country360.period_start,
            country360.kpi_code,
            country360.value,
            country360.status,
            country360.data_label,
            false AS is_proxy,
            NULL::text AS proxy_geo
           FROM ssot.country360
          WHERE ((country360.axis_code = '_T'::text) AND (country360.member_code = '_T'::text) AND (country360.basis = 'OUTTURN'::text))
        ), proxied AS (
         SELECT g.geo_code,
            c.frequency,
            c.period_start,
            c.kpi_code,
            c.value,
            c.status,
            c.data_label,
            true AS "?column?",
            g.policy_rate_proxy_geo
           FROM (ssot.dim_geo g
             JOIN ssot.country360 c ON (((c.geo_code = g.policy_rate_proxy_geo) AND (c.kpi_code = 'POLICY_RATE'::text) AND (c.axis_code = '_T'::text) AND (c.member_code = '_T'::text) AND (c.basis = 'OUTTURN'::text))))
          WHERE ((g.policy_rate_proxy_geo IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
                   FROM ssot.country360 o
                  WHERE ((o.geo_code = g.geo_code) AND (o.kpi_code = 'POLICY_RATE'::text) AND (o.frequency = c.frequency) AND (o.period_start = c.period_start) AND (o.axis_code = '_T'::text) AND (o.member_code = '_T'::text) AND (o.basis = 'OUTTURN'::text))))))
        ), u AS (
         SELECT own.geo_code,
            own.frequency,
            own.period_start,
            own.kpi_code,
            own.value,
            own.status,
            own.data_label,
            own.is_proxy,
            own.proxy_geo
           FROM own
        UNION ALL
         SELECT proxied.geo_code,
            proxied.frequency,
            proxied.period_start,
            proxied.kpi_code,
            proxied.value,
            proxied.status,
            proxied.data_label,
            proxied."?column?",
            proxied.policy_rate_proxy_geo
           FROM proxied
        )
 SELECT geo_code,
    frequency,
    period_start,
    (EXTRACT(year FROM period_start))::integer AS year,
    (EXTRACT(month FROM period_start))::integer AS month,
    max(value) FILTER (WHERE (kpi_code = 'GDP_REAL_GROWTH'::text)) AS gdp_real_growth,
    max(value) FILTER (WHERE (kpi_code = 'GDP_NOMINAL_USD'::text)) AS gdp_nominal_usd,
    max(value) FILTER (WHERE (kpi_code = 'GDP_PER_CAPITA_USD'::text)) AS gdp_per_capita_usd,
    max(value) FILTER (WHERE (kpi_code = 'GDP_CONSTANT_2015_USD'::text)) AS gdp_constant_2015_usd,
    max(value) FILTER (WHERE (kpi_code = 'CPI_YOY'::text)) AS cpi_yoy,
    max(value) FILTER (WHERE (kpi_code = 'UNEMPLOYMENT_RATE'::text)) AS unemployment_rate,
    max(value) FILTER (WHERE (kpi_code = 'POPULATION'::text)) AS population,
    max(value) FILTER (WHERE (kpi_code = 'CURRENT_ACCOUNT_PCT_GDP'::text)) AS current_account_pct_gdp,
    max(value) FILTER (WHERE (kpi_code = 'FISCAL_BALANCE_PCT_GDP'::text)) AS fiscal_balance_pct_gdp,
    max(value) FILTER (WHERE (kpi_code = 'GOV_DEBT_PCT_GDP'::text)) AS gov_debt_pct_gdp,
    max(value) FILTER (WHERE (kpi_code = 'GOV_REVENUE_PCT_GDP'::text)) AS gov_revenue_pct_gdp,
    max(value) FILTER (WHERE (kpi_code = 'GOV_EXPENDITURE_PCT_GDP'::text)) AS gov_expenditure_pct_gdp,
    max(value) FILTER (WHERE (kpi_code = 'EXPORTS_PCT_GDP'::text)) AS exports_pct_gdp,
    max(value) FILTER (WHERE (kpi_code = 'FDI_INFLOW_USD'::text)) AS fdi_inflow_usd,
    max(value) FILTER (WHERE (kpi_code = 'AGRI_VALUE_ADDED_USD'::text)) AS agri_value_added_usd,
    max(value) FILTER (WHERE (kpi_code = 'POLICY_RATE'::text)) AS policy_rate,
    bool_or(is_proxy) FILTER (WHERE (kpi_code = 'POLICY_RATE'::text)) AS policy_rate_is_proxy,
    max(proxy_geo) FILTER (WHERE (kpi_code = 'POLICY_RATE'::text)) AS policy_rate_proxy_geo,
    max(value) FILTER (WHERE (kpi_code = 'BOND_YIELD_10Y'::text)) AS bond_yield_10y,
    max(value) FILTER (WHERE (kpi_code = 'FX_USD_INDEX'::text)) AS fx_usd_index,
    max(value) FILTER (WHERE (kpi_code = 'FX_EUR_USD'::text)) AS fx_eur_usd,
    max(value) FILTER (WHERE ((kpi_code = 'OIL_BRENT'::text) AND (status <> 'PROJECTION'::text))) AS oil_brent_spot,
    max(value) FILTER (WHERE ((kpi_code = 'OIL_BRENT'::text) AND (status = 'PROJECTION'::text))) AS oil_brent_forecast,
    max(value) FILTER (WHERE ((kpi_code = 'OIL_WTI'::text) AND (status <> 'PROJECTION'::text))) AS oil_wti_spot,
    max(value) FILTER (WHERE ((kpi_code = 'OIL_WTI'::text) AND (status = 'PROJECTION'::text))) AS oil_wti_forecast,
    max(value) FILTER (WHERE (kpi_code = 'PARTNER_DEMAND'::text)) AS partner_demand,
    max(value) FILTER (WHERE (kpi_code = 'NON_OIL_GDP_GROWTH'::text)) AS non_oil_gdp_growth,
    max(value) FILTER (WHERE (kpi_code = 'PMI'::text)) AS pmi,
    max(status) FILTER (WHERE (kpi_code = 'GDP_REAL_GROWTH'::text)) AS gdp_real_growth_status,
        CASE
            WHEN bool_or((data_label = 'sample'::text)) THEN 'sample'::text
            WHEN bool_or((data_label = 'indicative'::text)) THEN 'indicative'::text
            ELSE 'real'::text
        END AS data_label_worst,
    (count(*))::integer AS n_kpis
   FROM u
  GROUP BY geo_code, frequency, period_start;


ALTER VIEW ssot.country360_wide OWNER TO fa;

