--
-- TOC entry 1789 (class 1259 OID 100920)
-- Name: country360_annual; Type: VIEW; Schema: ssot; Owner: fa
--

CREATE VIEW ssot.country360_annual AS
 SELECT country360.geo_code,
    country360.kpi_code,
    'A'::character(1) AS frequency,
    country360.period_start,
    country360.value,
    country360.unit,
    country360.status,
    country360.data_label,
    country360.source_code,
    country360.vintage_id,
    false AS is_rollup,
    1 AS n_obs
   FROM ssot.country360
  WHERE ((country360.frequency = 'A'::bpchar) AND (country360.axis_code = '_T'::text) AND (country360.member_code = '_T'::text) AND (country360.basis = 'OUTTURN'::text))
UNION ALL
 SELECT c.geo_code,
    c.kpi_code,
    'A'::bpchar AS frequency,
    (date_trunc('year'::text, (c.period_start)::timestamp with time zone))::date AS period_start,
        CASE k.aggregation
            WHEN 'SUM'::text THEN sum(c.value)
            WHEN 'AVG'::text THEN avg(c.value)
            ELSE (array_agg(c.value ORDER BY c.period_start DESC))[1]
        END AS value,
    max(c.unit) AS unit,
        CASE
            WHEN bool_or((c.status = 'PROJECTION'::text)) THEN 'PROJECTION'::text
            ELSE 'ACTUAL'::text
        END AS status,
        CASE
            WHEN bool_or((c.data_label = 'sample'::text)) THEN 'sample'::text
            WHEN bool_or((c.data_label = 'indicative'::text)) THEN 'indicative'::text
            ELSE 'real'::text
        END AS data_label,
    max(c.source_code) AS source_code,
    max(c.vintage_id) AS vintage_id,
    true AS is_rollup,
    (count(*))::integer AS n_obs
   FROM (ssot.country360 c
     JOIN ssot.dim_kpi k USING (kpi_code))
  WHERE ((c.frequency = ANY (ARRAY['Q'::bpchar, 'M'::bpchar, 'D'::bpchar])) AND (c.axis_code = '_T'::text) AND (c.member_code = '_T'::text) AND (c.basis = 'OUTTURN'::text) AND (NOT (EXISTS ( SELECT 1
           FROM ssot.country360 a
          WHERE ((a.geo_code = c.geo_code) AND (a.kpi_code = c.kpi_code) AND (a.frequency = 'A'::bpchar) AND (a.period_start = (date_trunc('year'::text, (c.period_start)::timestamp with time zone))::date) AND (a.axis_code = '_T'::text) AND (a.member_code = '_T'::text) AND (a.basis = 'OUTTURN'::text))))))
  GROUP BY c.geo_code, c.kpi_code, k.aggregation, (date_trunc('year'::text, (c.period_start)::timestamp with time zone));


ALTER VIEW ssot.country360_annual OWNER TO fa;

