--
-- TOC entry 1791 (class 1259 OID 100930)
-- Name: fiscal360_dxb; Type: VIEW; Schema: ssot; Owner: fa
--

CREATE VIEW ssot.fiscal360_dxb AS
 SELECT c.kpi_code,
    c.axis_code,
    c.member_code,
    cl.name_en AS member_name_en,
    cl.name_ar AS member_name_ar,
    cl.group_name,
    c.frequency,
    c.period_start,
    max(c.value) FILTER (WHERE (c.basis = 'BUDGET'::text)) AS budget,
    max(c.value) FILTER (WHERE (c.basis = 'OUTTURN'::text)) AS outturn,
    max(c.value) FILTER (WHERE (c.basis = 'PLAN'::text)) AS plan,
    (max(c.value) FILTER (WHERE (c.basis = 'OUTTURN'::text)) - max(c.value) FILTER (WHERE (c.basis = 'BUDGET'::text))) AS variance,
        CASE
            WHEN (max(c.value) FILTER (WHERE (c.basis = 'BUDGET'::text)) <> (0)::double precision) THEN (((100.0)::double precision * (max(c.value) FILTER (WHERE (c.basis = 'OUTTURN'::text)) - max(c.value) FILTER (WHERE (c.basis = 'BUDGET'::text)))) / max(c.value) FILTER (WHERE (c.basis = 'BUDGET'::text)))
            ELSE NULL::double precision
        END AS variance_pct,
    max(c.unit) AS unit,
    max(c.status) FILTER (WHERE (c.basis = 'OUTTURN'::text)) AS outturn_status,
        CASE
            WHEN bool_or((c.data_label = 'sample'::text)) THEN 'sample'::text
            WHEN bool_or((c.data_label = 'indicative'::text)) THEN 'indicative'::text
            ELSE 'real'::text
        END AS data_label_worst,
    max(c.source_code) AS source_code,
    max(c.vintage_id) AS vintage_id
   FROM ((ssot.country360 c
     LEFT JOIN ssot.dim_classification cl ON (((cl.axis_code = c.axis_code) AND (cl.member_code = c.member_code))))
     JOIN ssot.dim_kpi k ON ((k.kpi_code = c.kpi_code)))
  WHERE ((c.geo_code = 'DXB'::text) AND (k.category = 'FISCAL'::text))
  GROUP BY c.kpi_code, c.axis_code, c.member_code, cl.name_en, cl.name_ar, cl.group_name, c.frequency, c.period_start;


ALTER VIEW ssot.fiscal360_dxb OWNER TO fa;

