    geo_scope text DEFAULT 'ALL'::text NOT NULL,
    kpi_code text NOT NULL,
    axis_code text DEFAULT '_T'::text NOT NULL,
    member_code text DEFAULT '_T'::text NOT NULL,
    basis text DEFAULT 'OUTTURN'::text NOT NULL,
    frequency character(1) NOT NULL,
    unit_native text,
    unit_factor numeric DEFAULT 1 NOT NULL,
    transform text DEFAULT 'NONE'::text NOT NULL,
    status_rule text DEFAULT 'PERIOD_ENDED'::text NOT NULL,
    precedence_rank smallint DEFAULT 2 NOT NULL,
    data_label text DEFAULT 'real'::text NOT NULL,
    confidence_default numeric(3,2) DEFAULT 1.00 NOT NULL,
    active_from date DEFAULT CURRENT_DATE NOT NULL,
    active_to date,
    reviewed_by text,
    reviewed_at timestamp with time zone,
    notes text,
    CONSTRAINT kpi_source_map_basis_check CHECK ((basis = ANY (ARRAY['OUTTURN'::text, 'BUDGET'::text, 'PLAN'::text]))),
    CONSTRAINT kpi_source_map_check CHECK (((active_to IS NULL) OR (active_to > active_from))),
    CONSTRAINT kpi_source_map_confidence_default_check CHECK (((confidence_default >= (0)::numeric) AND (confidence_default <= (1)::numeric))),
    CONSTRAINT kpi_source_map_data_label_check CHECK ((data_label = ANY (ARRAY['real'::text, 'indicative'::text, 'sample'::text]))),
    CONSTRAINT kpi_source_map_frequency_check CHECK ((frequency = ANY (ARRAY['A'::bpchar, 'Q'::bpchar, 'M'::bpchar, 'D'::bpchar]))),
    CONSTRAINT kpi_source_map_precedence_rank_check CHECK ((precedence_rank >= 1)),
    CONSTRAINT kpi_source_map_status_rule_check CHECK ((status_rule = ANY (ARRAY['ESTIMATES_START_AFTER'::text, 'ALWAYS_ACTUAL'::text, 'ALWAYS_PROJECTION'::text, 'PERIOD_ENDED'::text]))),
    CONSTRAINT kpi_source_map_transform_check CHECK ((transform = ANY (ARRAY['NONE'::text, 'PCT_TO_RATIO'::text, 'RATIO_TO_PCT'::text, 'YOY_FROM_LEVEL'::text, 'EOP'::text, 'AVG'::text])))
);


ALTER TABLE ssot.kpi_source_map OWNER TO fa;

